#include "model.h"

#include <ctype.h>
#include <stdlib.h>
#include <string.h>

// This part (hash map) is generated by Claude
static int ht_lookup(const VocabBucket *buckets, uint32_t cap, const char *word) {
  uint32_t h = 0x811c9dc5u;
  for (const char *s = word; *s; s++) {
    h ^= (unsigned char)*s;
    h *= 0x01000193u;
  }
  uint32_t slot = h & (cap - 1);
  while (buckets[slot].index != -1) {
    if (strcmp(buckets[slot].word, word) == 0)
      return buckets[slot].index;
    slot = (slot + 1) & (cap - 1);
  }
  return 0;
}

int tokenize(const char *text, const Vocab *vocab, int *out_indices, int max_tokens) {
  int count = 0;

  size_t len = strlen(text);
  char *buffer = malloc(len + 1);
  if (! buffer) {
    out_indices[0] = 0;
    return 1;
  }

  size_t j = 0;
  for (size_t i = 0; i < len; i++) {
    unsigned char c = (unsigned char)text[i];
    if (ispunct(c)) {
      continue;
    }
    buffer[j++] = (char)tolower(c);
  }
  buffer[j] = '\0';

  char *saveptr = NULL;
  char *tok = strtok_r(buffer, " \t\n\r", &saveptr);
  while (tok && count < max_tokens) {
    out_indices[count++] = ht_lookup(vocab->buckets, vocab->cap, tok);
    tok = strtok_r(NULL, " \t\n\r", &saveptr);
  }

  free(buffer);

  if (count == 0) {
    out_indices[0] = 0;
    count = 1;
  }

  return count;
}


